def extract_version_from_apk(apk_path: str) -> tuple:
    """Extract versionCode and versionName from input APK using aapt."""
    vc, vn = 1, "1.0"
    try:
        aapt = os.path.join(_ANDROID_SDK, "aapt.exe") if os.name == "nt" else os.path.join(_ANDROID_SDK, "aapt")
        if not os.path.exists(aapt):
            aapt = "aapt"
        r = subprocess.run([aapt, "dump", "badging", apk_path],
                           capture_output=True, text=True, timeout=30)
        for line in r.stdout.splitlines():
            if line.startswith("versionCode="):
                vc = int(line.split("'")[1])
            elif line.startswith("versionName="):
                vn = line.split("'")[1]
    except Exception:
        pass
    return vc, vn

def _utf16_encode(s):
    """Encode string as Android binary XML UTF-16: 2-byte char_len + UTF-16LE + 2 null bytes."""
    encoded = s.encode("utf-16-le")
    char_len = len(s)
    return struct.pack("<H", char_len) + encoded + b"\x00\x00"

def patch_manifest_version(data: bytes, new_vc: int, new_vn: str) -> bytes:
    """Add android:versionCode and android:versionName to the <manifest> element.

    Parses binary Android XML, appends strings to string pool, rebuilds pool,
    shifts XML tree, and inserts attributes into the manifest element.
    """
    data = bytearray(data)
    try:
        # === Parse XML header ===
        xml_hdr_size = struct.unpack_from("<H", data, 2)[0]

        # === Parse string pool ===
        sp_off = xml_hdr_size
        sp_hdr_size = struct.unpack_from("<H", data, sp_off + 2)[0]
        sp_size = struct.unpack_from("<I", data, sp_off + 4)[0]
        sp_count = struct.unpack_from("<I", data, sp_off + 8)[0]
        sp_flags = struct.unpack_from("<I", data, sp_off + 16)[0]
        sp_strings_rel = struct.unpack_from("<I", data, sp_off + 20)[0]
        is_utf8 = bool(sp_flags & (1 << 8))
        if is_utf8:
            sys.stderr.write("[!] manifest is UTF-8, cannot patch\n")
            return bytes(data)

        off_arr_off = sp_off + sp_hdr_size
        abs_strs_off = sp_off + sp_strings_rel

        # Read string offsets
        offsets = []
        for i in range(sp_count):
            offsets.append(struct.unpack_from("<I", data, off_arr_off + i * 4)[0])

        # Find end of string data
        last_off = offsets[-1]
        p = abs_strs_off + last_off
        v = struct.unpack_from("<H", data, p)[0]
        char_len = v & 0x7FFF
        if v & 0x8000:
            char_len = (char_len << 16) | struct.unpack_from("<H", data, p + 2)[0]
            p += 4
        else:
            p += 2
        p += char_len * 2 + 2
        end_of_strs = p

        # Build new strings
        new_strs = [
            _utf16_encode("versionCode"),
            _utf16_encode("versionName"),
            _utf16_encode(str(new_vn)),
        ]
        new_indices = [sp_count, sp_count + 1, sp_count + 2]
        new_strs_data = b"".join(new_strs)

        # New offsets
        new_offs = []
        cursor = 0
        for s in new_strs:
            new_offs.append(end_of_strs - abs_strs_off + cursor)
            cursor += len(s)

        new_offs_bytes = b"".join(struct.pack("<I", o) for o in new_offs)
        raw_insert = len(new_offs_bytes) + len(new_strs_data)

        # Pad string pool to 4-byte alignment
        new_sp_total_raw = sp_size + raw_insert
        sp_pad = (4 - (new_sp_total_raw % 4)) % 4
        insert_size = raw_insert + sp_pad

        # Rebuild string pool
        new_sp_total = sp_size + insert_size
        new_sp_count = sp_count + len(new_strs)
        new_strs_start = sp_strings_rel + len(new_offs_bytes)

        sp_header = bytearray(data[sp_off:sp_off + sp_hdr_size])
        struct.pack_into("<I", sp_header, 4, new_sp_total)
        struct.pack_into("<I", sp_header, 8, new_sp_count)
        struct.pack_into("<I", sp_header, 20, new_strs_start)

        old_offsets = bytes(data[off_arr_off:off_arr_off + sp_count * 4])
        old_str_data = bytes(data[abs_strs_off:end_of_strs])

        new_sp = bytes(sp_header) + old_offsets + new_offs_bytes + old_str_data + new_strs_data + b"\x00" * sp_pad

        # Get XML tree (after string pool) - do NOT shift, just use directly
        tree_start = sp_off + sp_size
        tree_data = bytearray(data[tree_start:])

        # Find "manifest" string index dynamically
        manifest_idx = -1
        for i in range(sp_count):
            op = abs_strs_off + offsets[i]
            ov = struct.unpack_from("<H", data, op)[0]
            ocl = ov & 0x7FFF
            if ov & 0x8000:
                ocl = (ocl << 16) | struct.unpack_from("<H", data, op + 2)[0]
                op += 4
            else:
                op += 2
            raw = data[op:op + ocl * 2]
            try:
                s = raw.decode("utf-16-le")
                if s == "manifest":
                    manifest_idx = i
                    break
            except Exception:
                pass

        if manifest_idx < 0:
            sys.stderr.write("[!] 'manifest' string not found in pool\n")
            return bytes(data)

        # Find START_ELEMENT for manifest
        mpos = None
        pos = 0
        while pos < len(tree_data) - 8:
            ct = struct.unpack_from("<H", tree_data, pos)[0]
            cs = struct.unpack_from("<I", tree_data, pos + 4)[0]
            if cs < 8 or pos + cs > len(tree_data):
                break
            if ct == 0x0102:  # START_ELEMENT
                name_idx = struct.unpack_from("<i", tree_data, pos + 20)[0]
                if name_idx == manifest_idx:
                    mpos = pos
                    break
            pos += cs

        if mpos is None:
            sys.stderr.write("[!] manifest element not found\n")
            before = bytearray(data[:sp_off])
            result = bytearray(before) + bytearray(new_sp) + bytearray(tree_data)
            struct.pack_into("<I", result, 4, len(result))
            return bytes(result)

        # Build attributes
        android_ns = 34

        vc_attr = struct.pack("<IIi", android_ns, new_indices[0], -1)
        vc_attr += struct.pack("<HBB i", 20, 0, 0x10, new_vc)

        vn_attr = struct.pack("<IIi", android_ns, new_indices[1], new_indices[2])
        vn_attr += struct.pack("<HBB i", 20, 0, 0x03, new_indices[2])

        new_attrs = vc_attr + vn_attr
        elem_size = struct.unpack_from("<I", tree_data, mpos + 4)[0]
        attr_count = struct.unpack_from("<H", tree_data, mpos + 28)[0]
        attrs_end = mpos + 36 + attr_count * 20

        new_tree = (bytearray(tree_data[:attrs_end]) +
                    bytearray(new_attrs) +
                    bytearray(tree_data[attrs_end:]))

        struct.pack_into("<I", new_tree, mpos + 4, elem_size + len(new_attrs))
        struct.pack_into("<H", new_tree, mpos + 28, attr_count + 2)

        before = bytearray(data[:sp_off])
        result = bytearray(before) + bytearray(new_sp) + bytearray(new_tree)
        struct.pack_into("<I", result, 4, len(result))

        sys.stderr.write("[*] manifest patched: versionCode=%d, versionName=%s\n" % (new_vc, new_vn))
        return bytes(result)

    except Exception as e:
        sys.stderr.write("[!] manifest patch failed: %s\n" % e)
        import traceback
        traceback.print_exc()
        return bytes(data)

def patch_name(arsc: bytes, label: str) -> bytes:
    raw = label.encode("utf-8")
    n = len(OLD_NAME)
    if len(raw) > n:
        raw = raw[:n]
    raw += b" " * (n - len(raw))
    idx = arsc.find(OLD_NAME)
    if idx < 0:
        return arsc
    return arsc[:idx] + raw + arsc[idx + n:]

